import{_ as a,c as t,o as r,ax as i}from"./chunks/framework.DHqKNX4U.js";const m=JSON.parse('{"title":"Connecting Email Providers","description":"","frontmatter":{},"headers":[],"relativePath":"user-guides/email-providers/index.md","filePath":"user-guides/email-providers/index.md"}'),o={name:"user-guides/email-providers/index.md"};function s(n,e,h,l,d,c){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="connecting-email-providers" tabindex="-1">Connecting Email Providers <a class="header-anchor" href="#connecting-email-providers" aria-label="Permalink to &quot;Connecting Email Providers&quot;">​</a></h1><p>Open Archiver can connect to a variety of email sources to ingest and archive your emails. This section provides guides for connecting to popular email providers.</p><p>Choose your provider from the list below to get started:</p><ul><li><a href="./google-workspace.html">Google Workspace</a></li><li><a href="./microsoft-365.html">Microsoft 365</a></li><li><a href="./imap.html">Generic IMAP Server</a></li><li><a href="./oauth-mailbox.html">OAuth Mailbox (Outlook.com and personal accounts)</a></li><li><a href="./eml.html">EML Import</a></li><li><a href="./pst.html">PST Import</a></li><li><a href="./mbox.html">Mbox Import</a></li><li><a href="./merging-sources.html">Merging Ingestion Sources</a></li></ul><h2 id="what-gets-archived" tabindex="-1">What gets archived <a class="header-anchor" href="#what-gets-archived" aria-label="Permalink to &quot;What gets archived&quot;">​</a></h2><h3 id="drafts" tabindex="-1">Drafts <a class="header-anchor" href="#drafts" aria-label="Permalink to &quot;Drafts&quot;">​</a></h3><p>Unsent drafts from live mailboxes — Google Workspace, Microsoft 365 and IMAP — are <strong>not archived by default</strong>. A draft is not a record of anything: it was never sent, and it changes every time its author touches it. Archiving one goes wrong in both directions, depending on the provider.</p><p>Google replaces the underlying message on every save, so each auto-save arrives as a new message with new identifiers. Archived, they accumulate: one email that is still being written can leave a dozen copies behind, plus one more when it is finally sent.</p><p>Many IMAP servers do the opposite and keep a single Message-ID from the first save through to the sent message. The draft is archived first, and the message that was actually sent is then taken for a duplicate of it — so the archive keeps an unfinished body and never learns what was really sent.</p><p>Set <code>ARCHIVE_DRAFTS=true</code> if you need drafts kept. Note that both behaviours above come back with it.</p><p><strong>File imports are not affected.</strong> A PST, EML or mbox file is a snapshot you chose to hand over, and it is imported once rather than polled, so neither problem applies. Everything in the file is archived, drafts included, whatever <code>ARCHIVE_DRAFTS</code> is set to.</p><h3 id="junk-and-trash" tabindex="-1">Junk and Trash <a class="header-anchor" href="#junk-and-trash" aria-label="Permalink to &quot;Junk and Trash&quot;">​</a></h3><p>Junk and Trash folders are excluded by default on IMAP. Set <code>ALL_INCLUSIVE_ARCHIVE=true</code> to include them. This setting is separate from <code>ARCHIVE_DRAFTS</code> — asking for spam to be archived is not the same as asking for half-written messages.</p>',13)]))}const u=a(o,[["render",s]]);export{m as __pageData,u as default};
